solution:
interface ModuleDef {
  deps: string[]
  value: string
}

interface Exports {
  value?: string
}

function runLoader(modules: Record<string, ModuleDef>, entry: string): string[] {
  const log: string[] = []
  const cache = new Map<string, Exports>()

  function load(name: string): Exports {
    const cached = cache.get(name)
    if (cached) return cached
    if (!Object.hasOwn(modules, name)) throw new Error(`Cannot find module '${name}'`)
    const def = modules[name]
    const exports: Exports = {}
    cache.set(name, exports)
    log.push(`run ${name}`)
    for (const dep of def.deps) {
      const got = load(dep)
      log.push(`${name} got ${dep}=${got.value ?? '?'}`)
    }
    exports.value = def.value
    return exports
  }

  try {
    load(entry)
  } catch (error) {
    log.push(`error: ${error instanceof Error ? error.message : String(error)}`)
  }
  return log
}

The cache is filled with an empty exports object **before** the body runs, which is the whole trick: when a cycle leads back to a module that is still running, `cache.get` finds it and returns the half-built object instead of recursing forever, so the dependent sees `?` for its value, exactly like Node's partial `module.exports`. Every module therefore runs once, which also makes a diamond (two modules sharing one dependency) evaluate the shared module a single time. Missing names throw a real `Error`, and the top-level `try/catch` narrows the `unknown` catch variable before reading `message`. `Object.hasOwn` avoids treating inherited properties such as `toString` as modules, and `??` keeps an empty-string export distinct from an unset one. Each module is loaded once and each dependency edge is followed once, so time is O(V + E) and the cache is O(V).

