function toError(value: unknown): Error {
  if (value instanceof Error) return value
  if (typeof value === 'string') return new Error(value, { cause: value })
  if (typeof value === 'object' && value !== null && 'message' in value && typeof value.message === 'string') {
    const error = new Error(value.message, { cause: value })
    if ('name' in value && typeof value.name === 'string') error.name = value.name
    return error
  }
  return new Error(`Non-error thrown: ${safeString(value)}`, { cause: value })
}

function describeThrown(values: unknown[]): string[] {
  return values.map(value => {
    try {
      throw value
    } catch (caught) {
      const error = toError(caught)
      return `${error.name}: ${error.message}`
    }
  })
}

