interface TaskSpec {
  ms: number
  outcome: 'ok' | 'error' | 'string' | 'sync'
  value: string
}

function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms))
}

// Do not change: a task can fulfil, reject with an Error, reject with a bare string, or throw before returning a promise.
function startTask(spec: TaskSpec): Promise<string> {
  if (spec.outcome === 'sync') throw new Error(spec.value)
  return delay(spec.ms).then(() => {
    if (spec.outcome === 'error') throw new Error(spec.value)
    if (spec.outcome === 'string') throw spec.value
    return spec.value
  })
}

type Result<T, E = Error> = { ok: true; value: T } | { ok: false; error: E }

async function tryAsync<T>(fn: () => Promise<T>): Promise<Result<T>> {
  try {
    return { ok: true, value: await fn() }
  } catch (caught) {
    return { ok: false, error: toError(caught) }
  }
}

interface Summary {
  lines: string[]
  failed: number
}

async function runAll(specs: TaskSpec[]): Promise<Summary> {
  const results = await Promise.all(specs.map(spec => tryAsync(() => startTask(spec))))
  const lines = results.map(r => (r.ok ? `ok ${r.value}` : `fail ${r.error.message}`))
  return { lines, failed: results.filter(r => !r.ok).length }
}

