type Mod = { ready?: boolean }
const cache: Record<string, Mod> = {}
const out: string[] = []

const bodies: Record<string, (mod: Mod) => void> = {
  a(mod) {
    const b = load('b')
    out.push('a sees b.ready=' + b.ready)
    mod.ready = true
  },
  b(mod) {
    const a = load('a')
    out.push('b sees a.ready=' + a.ready)
    mod.ready = true
  },
